SELECT
	NEMO AS RF_NEMO,RF.COD_OFI AS RF_COD_OFI,COND_COD_OFI_001 AS RF_COND_COD_OFI_001,COND_COD_OFI_002 AS RF_COND_COD_OFI_002,COND_COD_OFI_003 AS RF_COND_COD_OFI_003,COND_COD_OFI_004 AS RF_COND_COD_OFI_004,
	COND_COD_OFI_005 AS RF_COND_COD_OFI_005,COND_COD_OFI_006 AS RF_COND_COD_OFI_006,COND_COD_OFI_007 AS RF_COND_COD_OFI_007,COND_COD_OFI_008 AS RF_COND_COD_OFI_008,COND_COD_OFI_009 AS RF_COND_COD_OFI_009,
	COND_COD_OFI_010 AS RF_COND_COD_OFI_010,COND_DIS_OFI AS RF_COND_DIS_OFI,DIAS_TR_SN_AC AS RF_DIAS_TR_SN_AC,DIAS_TR_ME_AC AS RF_DIAS_TR_ME_AC,EMI_PROV AS RF_EMI_PROV,ESTADO AS RF_ESTADO,
	RF.FAC_FRACC_OFE AS RF_FAC_FRACC_OFE,FEC_EMI AS RF_FEC_EMI,FEC_FIJ_CIE AS RF_FEC_FIJ_CIE,RF.FEC_VCTO AS RF_FEC_VCTO,RF.IND_BOLSON AS RF_IND_BOLSON,HORA_FIJ_CIE AS RF_HORA_FIJ_CIE,MONTO AS RF_MONTO,
	MONTO_SN_AC AS RF_MONTO_SN_AC,MONTO_ME_AC AS RF_MONTO_ME_AC,MONTO_MED_DI_AC AS RF_MONTO_MED_DI_AC,MONTO_MED_SN_AC AS RF_MONTO_MED_SN_AC,MONTO_X_PMED_DI AS RF_MONTO_X_PMED_DI,MONTO_X_PMED_SN AS RF_MONTO_X_PMED_SN,
	MONTO_X_TIR AS RF_MONTO_X_TIR,RAZON_SOCIAL AS RF_RAZON_SOCIAL,NUM_NEG AS RF_NUM_NEG,PRE_CIE_AN_AN AS RF_PRE_CIE_AN_AN,PRE_CIE_DI_AC AS RF_PRE_CIE_DI_AC,PRE_CIE_ME_AN AS RF_PRE_CIE_ME_AN,PRE_CIE_OFI AS RF_PRE_CIE_OFI,
	PRE_CIE_SN_AN AS RF_PRE_CIE_SN_AN,PRE_MAY AS RF_PRE_MAY,PRE_MAY_SN_AC AS RF_PRE_MAY_SN_AC,PRE_MED AS RF_PRE_MED,PRE_MED_SN_AC AS RF_PRE_MED_SN_AC,PRE_MEN AS RF_PRE_MEN,PRE_MEN_SN_AC AS RF_PRE_MEN_SN_AC,
	TENDEN AS RF_TENDEN,TIPO_CALCULO AS RF_TIPO_CALCULO,TIR_MED AS RF_TIR_MED,UNI_TRA AS RF_UNI_TRA,UNI_TRA_SN_AC AS RF_UNI_TRA_SN_AC,UNI_TRA_ME_AC AS RF_UNI_TRA_ME_AC,RF.COD_SERIE AS RF_COD_SERIE,
	RF.FAMILIA AS RF_FAMILIA,GENERICO AS RF_GENERICO,RF.MONEDA AS RF_MONEDA,TIR_MAY AS RF_TIR_MAY,TIR_MEN AS RF_TIR_MEN,DURATION_MED AS RF_DURATION_MED,MONTO_DURATION AS RF_MONTO_DURATION,CODIGO_ISIN AS RF_CODIGO_ISIN,
	
	COALESCE(SE.COD_SERIE,'') AS SE_COD_SERIE,COALESCE(COD_BCO,'') AS SE_COD_BCO,COALESCE(SE.COD_OFI,'') AS SE_COD_OFI,COALESCE(CORTE_MIN,0) AS SE_CORTE_MIN,REPLACE(COALESCE(SE.CLASIF_RIESGO,''),';','||') AS SE_CLASIF_RIESGO,COALESCE(IND_DIVISI,'') AS SE_IND_DIVISI,COALESCE(EMISOR,'') AS SE_EMISOR,
	COALESCE(SE.FAC_FRACC_OFE,0) AS SE_FAC_FRACC_OFE,COALESCE(SE.FAMILIA,'') AS SE_FAMILIA,COALESCE(FEC_COM_PPAG,'0001-01-01') AS SE_FEC_COM_PPAG,COALESCE(FEC_PRI_EMI,'0001-01-01') AS SE_FEC_PRI_EMI,COALESCE(SE.FEC_VCTO,'0001-01-01') AS SE_FEC_VCTO,COALESCE(SE.IND_BOLSON,'') AS SE_IND_BOLSON,
	COALESCE(IRF_INSCRIP,'') AS SE_IRF_INSCRIP,COALESCE(MONTO_EMI,0) AS SE_MONTO_EMI,COALESCE(NUM_AMORT,0) AS SE_NUM_AMORT,COALESCE(NUM_CAR_VAL,0) AS SE_NUM_CAR_VAL,COALESCE(NUM_CUPON,0) AS SE_NUM_CUPON,COALESCE(ORDEN,0) AS SE_ORDEN,COALESCE(PERI_PAGO_CUPON,0) AS SE_PERI_PAGO_CUPON,
	COALESCE(PLAZO,0) AS SE_PLAZO,COALESCE(RANGO_PLAZO,'') AS SE_RANGO_PLAZO,COALESCE(RANGO_TASA,'') AS SE_RANGO_TASA,COALESCE(TASA_NOMI_EMI,0) AS SE_TASA_NOMI_EMI,COALESCE(TERA,0) AS SE_TERA,COALESCE(TIPO_AMORT,'') AS SE_TIPO_AMORT,COALESCE(TIPO_REAJ,'') AS SE_TIPO_REAJ,
	COALESCE(TIPO_INSTRU,'') AS SE_TIPO_INSTRU,COALESCE(TIPO_INTERES,'') AS SE_TIPO_INTERES,COALESCE(TIPO_NOMINAL,'') AS SE_TIPO_NOMINAL,REPLACE(COALESCE(COMENTARIOS,''),';','||') AS SE_COMENTARIOS,COALESCE(FEC_INGRESO,'0001-01-01') AS SE_FEC_INGRESO,COALESCE(SE.MONEDA,'') AS SE_MONEDA,
	COALESCE(ORDEN_CLASIF_RIESGO,0) AS SE_ORDEN_CLASIF_RIESGO,COALESCE(TIPO_MONEDA_PAGO,'') AS SE_TIPO_MONEDA_PAGO,COALESCE(TASA_FISCAL,0) AS SE_TASA_FISCAL,COALESCE(IND_VENTA_CORTA,'') AS SE_IND_VENTA_CORTA,COALESCE(IND_ART104,'') AS SE_IND_ART104

FROM TBRFMI RF
LEFT JOIN TBRFSE SE ON RF.COD_SERIE = SE.COD_SERIE AND RF.FAMILIA = SE.FAMILIA
ORDER BY NEMO